from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost = OrderedDict()
        self.frequency = {}
        self.used_bytes = 0
        self.protected_bytes = 0
        self.protected_target = self.capacity_bytes // 2
        self.ghost_limit = 4096
        self.requests = 0

    def _bump(self, key):
        self.frequency[key] = min(255, self.frequency.get(key, 0) + 1)

    def _tick(self):
        self.requests += 1
        if self.requests % 1024 == 0:
            for key, value in list(self.frequency.items()):
                value //= 2
                if value:
                    self.frequency[key] = value
                else:
                    del self.frequency[key]

    def _remember(self, key, size, segment):
        self.ghost.pop(key, None)
        self.ghost[key] = (size, segment)
        while len(self.ghost) > self.ghost_limit:
            self.ghost.popitem(last=False)

    def _rebalance(self):
        while self.protected and self.protected_bytes > self.protected_target:
            key, size = self.protected.popitem(last=False)
            self.protected_bytes -= size
            self.probation[key] = size

    def _victim_key(self):
        if self.probation:
            return next(iter(self.probation))
        if self.protected:
            return next(iter(self.protected))
        return None

    def _evict_one(self):
        if self.probation:
            key, size = self.probation.popitem(last=False)
            segment = 0
        elif self.protected:
            key, size = self.protected.popitem(last=False)
            self.protected_bytes -= size
            segment = 1
        else:
            return None
        self.used_bytes -= size
        self._remember(key, size, segment)
        return key

    def access(self, key: int, size: int, now: int) -> list[int]:
        self._tick()

        if key in self.protected:
            stored_size = self.protected.pop(key)
            self.protected[key] = stored_size
            self._bump(key)
            return []

        if key in self.probation:
            stored_size = self.probation.pop(key)
            self.protected[key] = stored_size
            self.protected_bytes += stored_size
            self._bump(key)
            self._rebalance()
            return []

        size = max(0, int(size))
        if self.capacity_bytes == 0 or size > self.capacity_bytes:
            return []

        self._bump(key)
        ghost_entry = self.ghost.pop(key, None)
        if ghost_entry is not None:
            _, old_segment = ghost_entry
            step = max(1, self.capacity_bytes // 32)
            if old_segment:
                self.protected_target = min(
                    (self.capacity_bytes * 3) // 4,
                    self.protected_target + step,
                )
            else:
                self.protected_target = max(
                    self.capacity_bytes // 4,
                    self.protected_target - step,
                )

        victim = self._victim_key()
        if (
            ghost_entry is None
            and victim is not None
            and self.used_bytes + size > self.capacity_bytes
            and self.frequency[key] <= self.frequency.get(victim, 0)
        ):
            self._remember(key, size, 0)
            return []

        if ghost_entry is not None and ghost_entry[1]:
            self.protected[key] = size
            self.protected_bytes += size
        else:
            self.probation[key] = size
        self.used_bytes += size
        self._rebalance()

        evicted = []
        while self.used_bytes > self.capacity_bytes:
            old_key = self._evict_one()
            if old_key is None:
                break
            evicted.append(old_key)
        return evicted
